641: /// - for a non-finite (`NaN`, `inf`) or out-of-range (outside 0..=100) value.
642: pub fn finite_percent(v: &Value) -> Option<f64> {
643:     let f = match v {
644:         Value::Number(n) => n.as_f64()?,
645:         Value::String(s) => s.trim().parse::<f64>().ok()?,
