651: /// The TOTAL, order-independent ranking of two observations of the SAME window at an equal
652: /// instant, evaluated at `now`: (1) a known future reset beats a known past reset beats a missing
653: /// one (a past reset means the window is reset, whatever its share); (2) the higher
654: /// `used_percent`; (3) the later `resets_at`; (4) identical - either. `Greater` when `a` ranks
655: /// above `b`.
656: fn cmp_window_rank(
657:     a: (f64, Option<DateTime<FixedOffset>>),
658:     b: (f64, Option<DateTime<FixedOffset>>),
659:     now: DateTime<Utc>,
660: ) -> std::cmp::Ordering {
661:     let rank = |r: Option<DateTime<FixedOffset>>| match r {
662:         Some(t) if t.with_timezone(&Utc) > now => 2u8,
663:         Some(_) => 1,
664:         None => 0,
665:     };
666:     rank(a.1)
667:         .cmp(&rank(b.1))
668:         .then(a.0.clamp(0.0, 100.0).total_cmp(&b.0.clamp(0.0, 100.0)))
669:         .then(a.1.cmp(&b.1))
670: }
