685:         (Some(av), Some(bv)) => (av, bv),
686:         (None, Some(bv)) => return Some(bv.clone()),
687:         _ => return a,
688:     };
689:     let key = |w: &Window| {
690:         (
691:             w.used_percent,
692:             w.resets_at
693:                 .as_deref()
694:                 .and_then(|r| DateTime::parse_from_rfc3339(r).ok()),
695:         )
696:     };
697:     let mut wins: [Option<Window>; 2] = [None, None];
698:     let mut ats: [Option<DateTime<FixedOffset>>; 2] = [None, None];
