817:     r.tokens = Some(json!({
818:         "input": t.and_then(|t| minus(t.input, bt(|b| b.input))),
819:         "cached": t.and_then(|t| minus(t.cached, bt(|b| b.cached))),
820:         "output": t.and_then(|t| minus(t.output, bt(|b| b.output))),
821:         "thread_input": t.and_then(|t| t.input),
822:         "calls": u.calls,
823:         "max_input": u.max_input,
824:         "context_window": u.context_window,
