"C:\\Users\\Dmytro\\AppData\\Local\\Microsoft\\WindowsApps\\pwsh.exe" -Command "@'
# Read-only model of the reviewed selection/serialization operations, not a Rust test.
from itertools import permutations
A={'p':(30,1),'s':None}
B={'p':None,'s':(10,3)}
C={'p':(99,2),'s':None}
def merge(a,b):
    return {k:max([x for x in (a[k],b[k]) if x is not None],key=lambda x:(x[1],x[0]),default=None) for k in ('p','s')}
def recorded(o):
    at=max(v[1] for v in o.values() if v)
    return {k:(v[0],at) if v else None for k,v in o.items()}
for order in permutations((A,B,C)):
    r={'p':None,'s':None}
    for o in order:r=merge(r,o)
    assert r['p']==(99,2)
print('Direct merge: all six permutations retain primary 99 at t2')
ab=recorded(merge(A,B))
print('Serialize merged A/B and reload:',ab)
for pair in ((ab,C),(C,ab)):
    r=merge(*pair)
    print('Recorded selection:',r,'blocking=',r['p'][0]>=98 or r['s'][0]>=98)
# rollout_usage assigns r.window = w on every named observation.
r=None
for o in (C,B):
    if any(o.values()):r=o
print('Single-rollout final named observation:',r,'older primary lost=',r['p'] is None)
'@ | python -B -"

